# Re-enable Nagle Algorithm Write-Host "Re-enabling Nagle algorithm on all adapters..." -ForegroundColor Cyan $adapters = Get-NetAdapter | Where-Object { $_.Status -eq "Up" } foreach ($adapter in $adapters) { $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($adapter.InterfaceGuid)" if (Test-Path $regPath) { Remove-ItemProperty -Path $regPath -Name "TcpAckFrequency" -ErrorAction SilentlyContinue Remove-ItemProperty -Path $regPath -Name "TCPNoDelay" -ErrorAction SilentlyContinue Remove-ItemProperty -Path $regPath -Name "TcpDelAckTicks" -ErrorAction SilentlyContinue Write-Host " Re-enabled Nagle on: $($adapter.Name)" -ForegroundColor Gray } } Write-Host "Nagle algorithm has been re-enabled." -ForegroundColor Green